using BlaxtorGym.src.BlaxtorGym.Application.Services;
using BlaxtorGym.src.BlaxtorGym.Domain.Entities;
using BlaxtorGym.Tests.Fakes;
namespace BlaxtorGym.Tests.Services;
[TestClass] public class NotificacionServiceTests
{
    private FakeNotificacionRepository _notificaciones = null!; private FakeMembresiaRepository _membresias = null!; private FakeEmailService _email = null!; private NotificacionService _service = null!;
    [TestInitialize] public void Inicializar() { _notificaciones = new(); _membresias = new(); _email = new(); _service = new(_notificaciones, _membresias, _email); }
    [TestMethod] public async Task GenerarNotificacionesAsync_MembresiaVenceHoy_CreaNotificacion() { _membresias.Membresias.Add(new Membresia { Id = 3, ClienteId = 7, Activa = true, FechaVencimiento = DateTime.Today, Cliente = new Cliente { Id = 7, NombreCompleto = "Ana", Activo = true } }); await _service.GenerarNotificacionesAsync(); Assert.HasCount(1, _notificaciones.Notificaciones); Assert.IsTrue(_notificaciones.Notificaciones[0].Mensaje.Contains("vence hoy")); }
    [TestMethod] public async Task GenerarNotificacionesAsync_ClienteInactivo_NoCreaNotificacion() { _membresias.Membresias.Add(new Membresia { Id = 3, FechaVencimiento = DateTime.Today, Cliente = new Cliente { Activo = false } }); await _service.GenerarNotificacionesAsync(); Assert.IsEmpty(_notificaciones.Notificaciones); }
    [TestMethod] public async Task GenerarNotificacionesAsync_NotificacionExistente_NoDuplica() { var membresia = new Membresia { Id = 3, ClienteId = 7, Activa = true, FechaVencimiento = DateTime.Today, Cliente = new Cliente { Id = 7, NombreCompleto = "Ana", Activo = true } }; _membresias.Membresias.Add(membresia); _notificaciones.Notificaciones.Add(new Notificacion { MembresiaId = 3, Mensaje = "La membresía de Ana vence hoy, " + DateTime.Today.ToString("dd/MM/yyyy") + "." }); await _service.GenerarNotificacionesAsync(); Assert.HasCount(1, _notificaciones.Notificaciones); }
    [TestMethod] public async Task EnviarCorreoAsync_DatosValidos_UsaEmailYActualizaEstado() { var notificacion = new Notificacion { Id = 5, Mensaje = "Aviso", Cliente = new Cliente { NombreCompleto = "Ana", CorreoElectronico = "ana@example.com" }, Membresia = new Membresia { TipoMembresia = new TipoMembresia { Nombre = "Mensual" } } }; _notificaciones.Notificaciones.Add(notificacion); await _service.EnviarCorreoAsync(5); Assert.AreEqual(1, _email.CantidadLlamadas); Assert.AreEqual("ana@example.com", _email.Destinatario); Assert.IsTrue(_email.Asunto!.Contains("BlaxtorGym")); Assert.IsTrue(notificacion.Enviada); Assert.AreSame(notificacion, _notificaciones.Actualizada); }
    [TestMethod] public async Task EnviarCorreoAsync_NotificacionYaEnviada_LanzaExcepcion() { _notificaciones.Notificaciones.Add(new Notificacion { Id = 5, Enviada = true }); await Assert.ThrowsExactlyAsync<InvalidOperationException>(() => _service.EnviarCorreoAsync(5)); Assert.AreEqual(0, _email.CantidadLlamadas); }
    [TestMethod] public async Task EnviarCorreoAsync_ClienteSinCorreo_LanzaExcepcion() { _notificaciones.Notificaciones.Add(new Notificacion { Id = 5, Cliente = new Cliente() }); await Assert.ThrowsExactlyAsync<InvalidOperationException>(() => _service.EnviarCorreoAsync(5)); }
    [TestMethod] public async Task EnviarCorreoAsync_Inexistente_LanzaExcepcion() { await Assert.ThrowsExactlyAsync<InvalidOperationException>(() => _service.EnviarCorreoAsync(5)); }
}
